begin;
create extension if not exists pgtap with schema extensions;
select plan(6);
insert into auth.users(id) values('09000000-0000-4000-8000-000000000001');
insert into public.tenants(id,name,demo) values('19000000-0000-4000-8000-000000000001','Confirmation fictional',true);
insert into public.sites(id,tenant_id,name) values('29000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','Confirmation site');
insert into public.memberships(tenant_id,site_id,user_id,role,capabilities) values('19000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','09000000-0000-4000-8000-000000000001','RESIDENT',array['visits.invite']);
insert into public.invitations(id,tenant_id,site_id,owner_id,token_hash,expires_at) values('39000000-0000-4000-8000-000000000001','19000000-0000-4000-8000-000000000001','29000000-0000-4000-8000-000000000001','09000000-0000-4000-8000-000000000001',encode(extensions.digest(repeat('e',64),'sha256'),'hex'),now()+interval '1 day');
set local role anon;
select throws_ok($$select public.get_visitor_confirmation(repeat('e',64))$$,'P0001','Confirmation unavailable','unregistered invitation has no confirmation');
select public.submit_visitor_registration(repeat('e',64),'Fictional private guest',true,'{}');
select is(public.get_visitor_confirmation(repeat('e',64))->>'status','pending_entry','registered guest can refresh minimal confirmation');
select ok(not(public.get_visitor_confirmation(repeat('e',64)) ?| array['guest_name','answers','owner_id','token_hash']),'confirmation excludes names, answers, owner and secrets');
select throws_ok($$select public.submit_visitor_registration(repeat('e',64),'Replay',true,'{}')$$,'P0001','Invitation unavailable','confirmation does not allow registration replay');
select throws_ok($$select public.get_visitor_confirmation(repeat('f',64))$$,'P0001','Confirmation unavailable','unrelated token has no confirmation');
reset role;
update public.invitations set redeemed_at=now()-interval '61 minutes' where id='39000000-0000-4000-8000-000000000001';
set local role anon;
select throws_ok($$select public.get_visitor_confirmation(repeat('e',64))$$,'P0001','Confirmation unavailable','confirmation expires independently after one hour');
select * from finish();
rollback;
